#!/usr/bin/env bash
# Fine-tune SmolVLA-450M on Push-T (~4.3 h on one RTX 3090 at 1.3 step/s).
# Generated by `evla finetune`; run with --dry-run first to inspect the command.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."
export HF_ENDPOINT=${HF_ENDPOINT:-https://hf-mirror.com}
export TOKENIZERS_PARALLELISM=false
export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
.venv/bin/evla finetune -c configs/finetune_smolvla_pusht.yaml
